// public/js/features/patients-list/copy-team-labs.mjs
function buildTeamLabsCopyText() {
  var pinned = getPatients().filter(function(p) {
    return p && p.pinned && !p.archived;
  });
  var blocks = [];
  pinned.forEach(function(p) {
    var lines = formatLabsForCensoCompact(getLabHistory(p.id) || []);
    if (!lines.length) return;
    blocks.push(formatPatientNameForCenso(p.nombre) + "\n" + lines.join("\n"));
  });
  return { text: blocks.join("\n\n"), patientCount: pinned.length, labCount: blocks.length };
}
function copyTeamLabsForToday(showToast) {
  var built = buildTeamLabsCopyText();
  if (!built.text) {
    showToast("No hay laboratorios de hoy en los pacientes fijados.", "info");
    return;
  }
  copyTableText(built.text, function(ok) {
    showToast(
      ok ? "Laboratorios copiados (" + built.labCount + " de " + built.patientCount + " fijados)." : "No se pudo copiar los laboratorios.",
      ok ? "success" : "error"
    );
  });
}

// public/js/features/patients-list/copy-team-estado-actual.mjs
function buildTeamEstadoActualCopyText() {
  var pinned = getPatients().filter(function(p) {
    return p && p.pinned && !p.archived;
  });
  var blocks = [];
  pinned.forEach(function(p) {
    var text = getEstadoActualTextForPatient(p);
    if (!text) return;
    blocks.push(formatPatientNameForCenso(p.nombre) + "\n" + text);
  });
  return { text: blocks.join("\n\n"), patientCount: pinned.length, estadoCount: blocks.length };
}
function copyTeamEstadoActualForToday(showToast) {
  var built = buildTeamEstadoActualCopyText();
  if (!built.text) {
    showToast("No hay estado actual en los pacientes fijados.", "info");
    return;
  }
  copyTableText(built.text, function(ok) {
    showToast(
      ok ? "Estado actual copiado (" + built.estadoCount + " de " + built.patientCount + " fijados)." : "No se pudo copiar el estado actual.",
      ok ? "success" : "error"
    );
  });
}

